import React, { Component, Fragment } from "react";
import { MDBDataTable, MDBBtn } from "mdbreact";
import { Card, CardBody, CardHeader, Button } from "reactstrap";

class Clients extends Component {
  state = {
    rowData: [
      {
        id: "Tiger Nixon",
        name: "System Architect",
        createdBy: "Edinburgh",
        actions: "61",
        date: "2011/04/25",
        salary: "$320"
      },
      {
        id: "Garrett Winters",
        name: "Accountant",
        createdBy: "Tokyo",
        actions: (
          <MDBBtn color="purple" outline size="sm">
            Button
          </MDBBtn>
        ),
        date: "2011/07/25",
        salary: "$170"
      }
    ]
  };
  render() {
    const data = {
      columns: [
        {
          label: "Id",
          field: "id",
          sort: "asc"
        },
        {
          label: "Name",
          field: "name",
          sort: "asc"
        },
        {
          label: "CreatedBy",
          field: "createdBy",
          sort: "asc"
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc"
        }
      ],
      rows: [this.state.rowData.rows]
    };

    return (
      <Card>
        <CardHeader>
          <h4>Clients</h4>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}
export default Clients;
